#!/usr/bin/env node
/**
 * Loads database/seed.sql (generated by scripts/build-dataset.mjs) into MariaDB.
 *   npm run db:seed
 */
import mysql from 'mysql2/promise'
import { readFileSync } from 'node:fs'
import { dbConfig } from './env.mjs'

const sql = readFileSync(new URL('../database/seed.sql', import.meta.url), 'utf8')
const conn = await mysql.createConnection({ ...dbConfig, multipleStatements: true })

const started = Date.now()
await conn.query(sql)
const [[counts]] = await conn.query(`SELECT
  (SELECT COUNT(*) FROM products) AS products,
  (SELECT COUNT(*) FROM categories) AS categories,
  (SELECT COUNT(*) FROM product_images) AS images,
  (SELECT COUNT(*) FROM posts) AS posts,
  (SELECT COUNT(*) FROM catalogs) AS catalogs,
  (SELECT COUNT(*) FROM dealers) AS dealers`)
console.log(`✔ seeded in ${Date.now() - started}ms`, counts)
await conn.end()
